async function api(path, options={}) {
 const resp=await fetch('/api/'+path,{cache:'no-store',...options});
 let body;try{body=await resp.json()}catch{throw new Error('Server returned an invalid response');}
 if(!resp.ok||body?.ok===false)throw new Error(body.error||'The service is unavailable');
 return body;
}
