const speedTargets={Spatial:[18,30,45,75,110],Memory:[15,18,25,40,55],Reasoning:[18,25,35,50,75]};
const clipMs=ms=>Math.max(0,Math.min(900000,Math.round(Number(ms)||0)));
function timeTier(task,ms){const sec=clipMs(ms)/1000,aim=speedTargets[task.d][task.lv-1];return sec<=aim?{name:'Within reference window',factor:1}:sec<=aim*2?{name:'Extended time',factor:.85}:{name:'Longer time',factor:.7};}
