const state={screen:'intro',mode:'anonymous',name:'',q:0,ratings:Array(12).fill(null),details:Array(12).fill(null),answers:Array(15).fill(null),timeMs:Array(27).fill(0),activeQuestion:null,activeSince:null,exposureRemain:8000,exposureTick:0,seen:new Set(),exposed:false,timer:null,deadline:0,strategy:'unsure',community:null,hasSubmitted:false,submissionId:null,deletionToken:null,publicEntry:false,network:false,networkError:'',entries:[],nextCursor:null,chartOnly:false,consent:false};
const strategies=['words or logical rules','nonvisual spatial awareness','actual mental pictures','a mixture of strategies','unsure'];
function score(){
 const imagery=state.ratings.reduce((a,b)=>a+(b??0),0);
 const detail=state.details.reduce((a,b)=>a+(b??0),0);
 const per=Object.fromEntries(['Spatial','Memory','Reasoning'].map(d=>[d,tasks.reduce((sum,t,i)=>sum+(t.d===d&&state.answers[i]===t.a?1:0),0)]));
 const correct=Object.values(per).reduce((a,b)=>a+b,0);
 const weighted=tasks.reduce((a,t,i)=>a+(state.answers[i]===t.a?t.lv:0),0);
 const timed=tasks.reduce((a,t,i)=>a+(state.answers[i]===t.a?t.lv*timeTier(t,state.timeMs[12+i]).factor:0),0);
 const category=stages.findIndex(t=>imagery>=t.min&&imagery<=t.max);
 const features=Object.fromEntries(['Contours','Color','Background','Motion','Stability'].map(group=>{const items=imageryItems.map((item,i)=>({...item,index:i})).filter(item=>item.group===group);return [group,Math.round(100*items.reduce((a,item)=>a+(state.details[item.index]??0),0)/(items.length*4))]}));
 const mismatches=state.ratings.filter((r,i)=>Math.abs(r-(state.details[i]??r))>=3).length;
 const veryFast=state.timeMs.slice(0,12).filter(ms=>ms>0&&ms<1200).length;
 const activeSeconds=state.timeMs.reduce((sum,ms)=>sum+ms,0)/1000;
 return {imagery,detail,features,mismatches,veryFast,activeSeconds,per,correct,weighted,timed:Number(timed.toFixed(1)),category};
}
function startQuestionTiming(n){stopQuestionTiming();state.activeQuestion=n;state.activeSince=document.hidden?null:performance.now();}
function stopQuestionTiming(){if(state.activeQuestion!==null&&state.activeSince!==null){state.timeMs[state.activeQuestion]+=performance.now()-state.activeSince;}state.activeQuestion=null;state.activeSince=null;}
document.addEventListener('visibilitychange',()=>{if(document.hidden&&state.activeSince!==null){state.timeMs[state.activeQuestion]+=performance.now()-state.activeSince;state.activeSince=null;}else if(!document.hidden&&state.activeQuestion!==null&&state.activeSince===null){state.activeSince=performance.now();}if(state.exposed)state.exposureTick=performance.now();});
