function pct(v,max){return Math.round(v/max*100)}
function miniStat(d,v){return `<div class="metric"><div class="row between"><span class="lbl">${esc(d)}</span><strong>${v}/5</strong></div><div class="bar"><i style="width:${v*20}%"></i></div><div class="fine">${v===5?'All challenges correct':v===0?'No correct answers in this set':`${pct(v,5)}% correct on this set`}</div></div>`}
function stageTiles(current){return `<div class="stages">${stages.map((s,i)=>`<div class="stage-item ${i===current?'active':''}"><div class="stage-line" style="background:${s.color}"></div><strong>${esc(s.short)}</strong><span>${esc(s.plain)}</span></div>`).join('')}</div>`;}
function resourcesHTML(){return `<div class="stack">${sources.map(s=>`<div class="resource"><a href="${s[2]}" target="_blank" rel="noopener noreferrer">${esc(s[0])} ↗</a><p>${esc(s[1])}</p></div>`).join('')}</div>`;}
function featuresHTML(s){return Object.entries(s.features).map(([name,value])=>`<div class="feature-line"><div class="feature-row"><b>${esc(name)}</b><span>${value}% of this quiz's feature scale</span></div><div class="feature-track"><i style="width:${value}%"></i></div></div>`).join('');}
function timeRows(){return tasks.map((t,i)=>{const correct=state.answers[i]===t.a,tier=timeTier(t,state.timeMs[12+i]),earned=correct?Number((t.lv*tier.factor).toFixed(2)):0,seconds=(state.timeMs[12+i]/1000).toFixed(1);return `<tr><td>${esc(t.d)} ${t.lv}</td><td>${correct?'✓ Correct':'✕ Incorrect'}</td><td>${seconds}s</td><td>${correct?tier.factor+'×':'—'}</td><td><strong>${earned.toFixed(2)}</strong></td></tr>`}).join('');}
function renderPersonal(){clearCountdown();state.screen='personal';const s=score();const cat=stages[s.category];const diff= ['Spatial','Memory','Reasoning'].map(d=>{const qs=tasks.map((t,i)=>({...t,index:i})).filter(t=>t.d===d);const highest=Math.max(0,...qs.filter(t=>state.answers[t.index]===t.a).map(t=>t.lv));return `<div class="metric"><div class="lbl">${d} levels 1–5</div><div class="diff-grid">${qs.map(t=>`<span class="level-dot ${state.answers[t.index]===t.a?'hit':'miss'}" title="Level ${t.lv}: ${state.answers[t.index]===t.a?'Correct':'Incorrect'}">${t.lv}</span>`).join('')}</div><div class="fine" style="margin-top:10px">Highest level correct: ${highest}/5</div></div>`}).join(''); const missed=tasks.map((t,i)=>({...t,index:i})).filter(t=>state.answers[t.index]!==t.a);articleFrame(`<section class="hero"><div class="eyebrow">Your private results · Before the community dashboard</div><h1>Your mind's eye, <span class="gradient">explained.</span></h1><p class="lede">${state.name&&state.mode==='named'?`For ${esc(state.name)}. `:''}Your imagery experience and your reasoning-task performance are different measurements. Here's what your answers indicate — and what they do not.</p></section><div class="grid"><div class="metric"><div class="lbl">Visual imagery rating</div><div class="big" style="color:${cat.color}">${s.imagery}<span class="fine"> / 48</span></div><div class="bar"><i style="width:${pct(s.imagery,48)}%;background:${cat.color}"></i></div><strong>${esc(cat.term)}</strong><div class="fine">${esc(cat.plain)}</div></div><div class="metric"><div class="lbl">Processing challenges</div><div class="big">${s.correct}<span class="fine"> / 15 correct</span></div><div class="bar"><i style="width:${pct(s.correct,15)}%"></i></div><div class="fine">${s.weighted} / 45 difficulty-weighted · ${s.timed.toFixed(1)} / 45 time-adjusted</div></div></div><section class="card topspace"><div class="kicker">01 · Visualization spectrum</div><h2 class="h2">${esc(cat.term)} <span class="muted small">· ${esc(cat.plain)}</span></h2><p>${esc(cat.description)}</p>${stageTiles(s.category)}<details><summary>Read all five imagery terms in plain English</summary><div class="topspace">${stages.map(t=>`<div class="legend-row"><span class="dot" style="background:${t.color}"></span><div><strong>${esc(t.term)}</strong><span>${esc(t.plain)} · Quiz score ${t.min===t.max?t.min:`${t.min}–${t.max}`}/48</span></div><span></span></div>`).join('')}</div></details><p class="fine topspace">These five descriptive ranges are <strong>custom to this 12-item questionnaire</strong>. They are not clinically established diagnostic stages or equivalent to VVIQ cutoffs. The names “aphantasia,” “hypophantasia,” and “hyperphantasia” are used in research, but boundaries differ across studies.</p><div class="hr"></div><div class="kicker">02 · Visual detail profile</div><h2 class="h2">What can you actually see?</h2><p class="small muted">Each bar combines specific feature choices, rather than repeating the same “vivid” rating. It describes your reported experience; these are custom scales, not validated tests of truthfulness.</p><div class="grid"><div class="metric"><div class="lbl">Overall self-rated imagery</div><div class="big">${s.imagery}<span class="fine"> / 48</span></div></div><div class="metric"><div class="lbl">Specific-feature descriptions</div><div class="big">${s.detail}<span class="fine"> / 48</span></div></div></div><div class="topspace">${featuresHTML(s)}</div>${s.mismatches>=3||s.veryFast>=5?`<div class="notice topspace"><strong>Review suggested:</strong> ${s.mismatches>=3?`${s.mismatches} pairs of ratings described noticeably different detail levels. This can be genuine — reconsider only if an answer was accidental. `:''}${s.veryFast>=5?`Several imagery questions were completed in under 1.2 seconds. Rapid answers can be valid, but rereading may improve accuracy.`:''}</div>`:'<p class="fine topspace">No major response-pattern review notices. This does not verify or authenticate subjective answers.</p>'}<div class="hr"></div><div class="kicker">03 · Cognitive challenge profile</div><h2 class="h2">Performance across three domains</h2><div class="grid3">${Object.entries(s.per).map(([d,v])=>miniStat(d,v)).join('')}</div><div class="grid3 topspace">${diff}</div><div class="metric topspace"><div class="lbl">Accuracy plus background time grade</div><div class="big">${s.timed.toFixed(1)}<span class="fine"> / 45 points</span></div><p class="small muted topspace">A correct response gets full difficulty points within a reference time, 85% if it takes up to twice as long, and 70% thereafter. Incorrect responses receive zero. Targets vary by difficulty and domain; they are illustrative, not validated norms. Time while the browser is hidden and the memory-pattern display interval are excluded.</p><details><summary>See how all 15 questions were timed and graded</summary><div style="overflow-x:auto"><table class="time-table"><thead><tr><th>Task</th><th>Accuracy</th><th>Time</th><th>Grade</th><th>Points</th></tr></thead><tbody>${timeRows()}</tbody></table></div></details></div><details class="topspace"><summary>Review ${missed.length} missed questions and explanations</summary><div class="topspace">${missed.length?missed.map(t=>`<div class="review-entry"><strong>${esc(t.d)} · Level ${t.lv}: ${esc(t.t)}</strong><p class="small muted">Your response: ${esc(t.o[state.answers[t.index]])}</p><p class="small">Correct answer: <strong>${esc(t.o[t.a])}</strong></p><p class="fine">${esc(t.e)}</p></div>`).join(''):'Every question was answered correctly.'}</div></details><p class="fine topspace">The levels increase in complexity, but this short set has not been standardized. A wrong answer does not establish a cognitive limitation, and correct answers do not indicate intelligence or clinical status. People may use verbal, rule-based, or nonvisual spatial strategies.</p><div class="hr"></div><h3 class="h3">How did you solve the challenges?</h3><p class="small muted">Select the strategy you used most. This adds context to your results and does not affect your score.</p><div class="stack">${strategies.map((st,i)=>`<label class="selection"><input type="radio" name="strategy" value="${esc(st)}" ${state.strategy===st?'checked':''}><span>${esc(st.charAt(0).toUpperCase()+st.slice(1))}</span></label>`).join('')}</div><div class="insight topspace"><strong>What the combination may mean</strong><p class="small" style="margin-top:5px">${s.imagery<=12&&s.correct>=10?'You report little or no visual imagery while successfully answering many processing questions. This pattern is compatible with effective nonvisual problem-solving; imagery vividness and cognitive performance are not the same thing.':s.imagery<=12?'You describe weak or absent visual imagery. These challenge scores cannot tell whether any errors came from memory load, unfamiliarity, attention, strategy or imagery.': 'You describe at least some voluntary mental imagery. Your task results show how you handled these particular challenges, not whether you depend on imagery to think.'}</p></div></section><section class="card topspace"><div class="kicker">04 · Evidence & further reading</div><h2 class="h2">What research can — and cannot — tell us</h2><p class="small muted">The VVIQ is a more established research questionnaire for vividness. There is ongoing debate about thresholds and assessment. Studies disagree about which specific working-memory tasks are affected; some show comparable performance using nonvisual strategies, whereas others report deficits on certain tests. Response speed and feature questionnaires do not independently establish aphantasia. Volunteer survey percentages are not population prevalence.</p>${resourcesHTML()}<div class="notice topspace"><strong>Medical note:</strong> Aphantasia is generally studied as a difference in subjective visual imagery, not as a diagnosis made from this quiz. If a previously normal ability to visualize disappeared suddenly, discuss that change with a medical professional.</div></section><section class="card topspace" id="sharebox"><div class="kicker">05 · Optional contribution</div><h2 class="h2">${getSharedFlag()?'Add your scores to the collective picture?':'Save your result to this device’s chart?'}</h2><p class="muted small">Your results stay private unless you explicitly choose to save or submit them. ${getSharedFlag()?'An online submission saves':'A local entry saves'} your imagery band, overall feature score, accuracy, time-adjusted challenge score, scores by domain and chosen processing strategy. ${state.mode==='named'?`Your name “${esc(state.name)}” is stored only if you also opt in to an individual public entry.`:'No name is required or collected.'}</p><div class="sharing"><label class="selection"><input type="checkbox" id="consent" ${state.consent?'checked':''} ${state.hasSubmitted?'disabled':''}><span><b>${getSharedFlag()?'I consent to adding my scored summary to the collective percentages.':'Save my results on this device only.'}</b><small>${getSharedFlag()?'Only scores, imagery category, and strategy are retained, not raw answers or timing arrays. The charts include anonymized submissions.':'This copy cannot publish your data online. Saved scores appear in this browser only.'}</small></span></label><label class="selection topspace"><input type="checkbox" id="individualEntry" ${state.publicEntry?'checked':''} ${state.hasSubmitted?'disabled':''}><span><b>Also list my individual summary in the participant results</b><small>Optional and off by default. ${state.mode==='named'?`If you check this, “${esc(state.name)}” and summary scores will be visible to everyone.`:'If you check this, your summary scores will appear under “Anonymous”.'} This is separate from the collective percentages.</small></span></label><p class="fine topspace">Once you publish, you can use a private recovery code to delete your submission. Clearing this browser may remove its saved copy, so keep the code if deletion matters to you.</p><div class="row wraprow topspace"><button class="btn" id="submit" ${state.hasSubmitted?'disabled':''}>${state.hasSubmitted?(getSharedFlag()?'Already published ✓':'Saved on device ✓'):(getSharedFlag()?'Publish and see collective chart →':'Save and see this-device chart →')}</button><button class="btn secondary" id="noShare">${state.hasSubmitted?(getSharedFlag()?'Open collective results →':'Open this-device chart →'):(getSharedFlag()?'View chart without sharing →':'View this-device chart without saving →')}</button></div><p id="submitStatus" class="hint topspace" role="status"></p></div></section><div class="row wraprow topspace"><button class="btn secondary" id="copyMe">Copy my results</button><button class="btn tertiary" id="restart">Start a new assessment</button></div>`);
$$('input[name="strategy"]').forEach(i=>i.addEventListener('change',e=>state.strategy=e.target.value));$('#consent').addEventListener('change',e=>{state.consent=e.target.checked});$('#individualEntry').addEventListener('change',e=>{state.publicEntry=e.target.checked});$('#submit').addEventListener('click',submitAndOpen);$('#noShare').addEventListener('click',()=>renderCollective());$('#copyMe').addEventListener('click',async()=>{const t=`Mind's Eye Atlas — personal results\n${cat.term} (${cat.plain})\nImagery: ${s.imagery}/48\nSpecific imagery details: ${s.detail}/48\nChallenges: ${s.correct}/15 correct; time-adjusted ${s.timed.toFixed(1)}/45\nSpatial: ${s.per.Spatial}/5 · Memory: ${s.per.Memory}/5 · Reasoning: ${s.per.Reasoning}/5\nExploratory test; not a medical diagnosis.`;await copyText(t,'copyMe')});$('#restart').addEventListener('click',restart);}
function $$(s){return [...document.querySelectorAll(s)]}
async function copyText(t,id){try{await navigator.clipboard.writeText(t);if(id){const b=$('#'+id);if(b){const old=b.textContent;b.textContent='Copied ✓';setTimeout(()=>{if(b.isConnected)b.textContent=old},1800)}}}catch{window.prompt('Copy this text:',t)}}
function restart(){clearCountdown();stopQuestionTiming();Object.assign(state,{screen:'intro',mode:'anonymous',name:'',q:0,ratings:Array(12).fill(null),details:Array(12).fill(null),answers:Array(15).fill(null),timeMs:Array(27).fill(0),activeQuestion:null,activeSince:null,exposureRemain:8000,exposureTick:0,seen:new Set(),exposed:false,strategy:'unsure',hasSubmitted:false,submissionId:null,deletionToken:null,publicEntry:false,consent:false});renderIntro()}
let memoryArchive=[];function deviceAdd(result){let local=[];try{local=JSON.parse(localStorage.getItem('mindseye-local-v1')||'[]')||[];}catch{}if(local.some(x=>x.id===result.id))return;local.push(result);memoryArchive=local.slice(-500);try{localStorage.setItem('mindseye-local-v1',JSON.stringify(memoryArchive));}catch{state.networkError='This browser cannot save offline results permanently; this session is temporary.';}}
function deviceGet(){try{return JSON.parse(localStorage.getItem('mindseye-local-v1')||'[]')||memoryArchive}catch{return memoryArchive}}
function getSharedFlag(){return state.network}
async function submitAndOpen(){
 if(state.hasSubmitted){renderCollective();return;}
 if(!state.consent){$('#submitStatus').textContent='Consent is required to save a contribution.';return;}
 const b=$('#submit');b.disabled=true;b.textContent='Saving result…';
 const id=state.submissionId||(state.submissionId=(crypto.randomUUID?.()||newDeletionToken()));
 const token=state.deletionToken||(state.deletionToken=newDeletionToken());
 const base={id,version:2,name:state.mode==='named'&&state.publicEntry?state.name.trim().slice(0,30):null,
  publicEntry:state.publicEntry,consent:true,ratings:state.ratings.slice(),details:state.details.slice(),
  answers:state.answers.slice(),timeMs:state.timeMs.map(clipMs),strategy:state.strategy,deletionToken:token};
 try{
  if(getSharedFlag()){
   await api('submit',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(base)});
   try{localStorage.setItem('mindseye-recovery-v2',recoveryCode())}catch{}
  }else{
   const s=score();deviceAdd({id:base.id,name:base.name,public_entry:Number(state.publicEntry),assessment_version:2,
    imagery_score:s.imagery,detail_score:s.detail,timed_score:s.timed,category:s.category,total_correct:s.correct,
    weighted:s.weighted,spatial:s.per.Spatial,memory:s.per.Memory,reasoning:s.per.Reasoning,
    strategy:base.strategy,created_at:new Date().toISOString()});
  }
  state.hasSubmitted=true;renderCollective();
 }catch(err){$('#submitStatus').textContent='Not saved. '+(err.message||'Storage unavailable')+'. You can retry.';
  b.disabled=false;b.textContent='Retry publishing →';}
}
const emptyStats=()=>({total:0,buckets:[0,0,0,0,0],domains:{spatial:0,memory:0,reasoning:0},imageryAverage:0});
function deriveLocal(){const rows=deviceGet().filter(r=>r.assessment_version===2);const stats=emptyStats();stats.total=rows.length;for(const r of rows){if(Number.isInteger(r.category)&&r.category>=0&&r.category<5)stats.buckets[r.category]++;for(const [d,k] of [['spatial','spatial'],['memory','memory'],['reasoning','reasoning']])stats.domains[d]+=Number(r[k])||0;stats.imageryAverage+=Number(r.imagery_score)||0;}if(rows.length){for(const k of Object.keys(stats.domains))stats.domains[k]/=rows.length;stats.imageryAverage/=rows.length;}return {stats,rows:rows.filter(r=>r.public_entry).map((r,i)=>({...r,seq:i+1})).reverse()};}
async function loadStats(){if(!getSharedFlag())return deriveLocal().stats;return api('stats');}
async function loadEntries(cursor=null){if(!getSharedFlag())return {entries:deriveLocal().rows.slice(cursor?Number(cursor):0,(cursor?Number(cursor):0)+25),nextCursor:((cursor?Number(cursor):0)+25<deriveLocal().rows.length)?String((cursor?Number(cursor):0)+25):null};return api('entries'+(cursor?'?cursor='+encodeURIComponent(cursor):''));}
function ringSVG(counts){const total=counts.reduce((a,b)=>a+b,0);const radius=41,circ=2*Math.PI*radius;let offset=0;let paths='';counts.forEach((v,i)=>{if(!v)return;const len=v/total*circ;const gap=total>0&&counts.filter(x=>x>0).length>1?Math.min(1.25,len*.16):0;paths+=`<circle cx="50" cy="50" r="${radius}" fill="none" stroke="${stages[i].color}" stroke-width="16" stroke-dasharray="${Math.max(0,len-gap)} ${circ}" stroke-dashoffset="${-offset-gap/2}" />`;offset+=len;});return `<div class="donut" role="img" aria-label="Circular chart showing percentages of five imagery categories"><svg viewBox="0 0 100 100" aria-hidden="true"><circle cx="50" cy="50" r="41" fill="none" stroke="#2a3653" stroke-width="16"/>${paths}</svg><div class="center"><b>${total.toLocaleString()}</b><span>voluntary<br>responses</span></div></div>`;}
function ringSmall(value,title,color){const v=Math.max(0,Math.min(1,Number(value)||0)),circ=2*Math.PI*38;return `<div class="row" style="gap:0"><div class="tiny-donut"><svg viewBox="0 0 100 100" aria-hidden="true"><circle cx="50" cy="50" r="38" stroke="#2a3653" stroke-width="13" fill="none"/><circle cx="50" cy="50" r="38" stroke="${color}" stroke-width="13" fill="none" stroke-dasharray="${circ*v} ${circ}"/></svg></div><div class="tiny-center">${Math.round(v*100)}%</div><div style="padding-left:12px"><div style="font-weight:760">${title}</div><div class="fine">Average correct across 5 challenges</div></div></div>`;}
function shortDate(str){try{const v=String(str||'');const iso=v.includes('T')?v:v.replace(' ','T');return new Date(/[zZ]|[+-]\d\d:?\d\d$/.test(iso)?iso:iso+'Z').toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'})}catch{return 'Recent'}}
function entriesHTML(){if(!state.entries.length)return '<p class="muted small">No published entries yet.</p>';return state.entries.map(r=>{const c=stages[Number(r.category)]||stages[0];return `<div class="cohort"><div><div class="name">${esc(r.name||'Anonymous')} <span class="fine" style="font-weight:400">· ${esc(shortDate(r.created_at))}</span></div><div class="detail"><span class="dot" style="background:${c.color};height:8px;width:8px"></span> ${esc(c.term)} · Imagery ${Number(r.imagery_score)}/48</div></div><div style="text-align:right"><div class="name">${Number(r.total_correct)}/15 <span class="fine">correct</span></div><div class="detail">S ${Number(r.spatial)}/5 · M ${Number(r.memory)}/5 · R ${Number(r.reasoning)}/5 · Time ${Number(r.timed_score||0).toFixed(1)}/45 · Detail ${Number(r.detail_score||0)}/48</div></div></div>`}).join('');}
async function renderCollective(){clearCountdown();state.screen='collective';articleFrame(`<div class="hero"><div class="eyebrow">Community imagery spectrum</div><h1>Many minds. <span class="gradient">Different ways of seeing.</span></h1><p class="lede">Every contribution changes the shared picture. Percentages reflect the people who chose to take and share this test — not population prevalence.</p></div><div class="card"><p class="muted">Loading collective responses…</p></div>`);let stats,entryData;try{[stats,entryData]=await Promise.all([loadStats(),loadEntries()]);state.networkError='';}catch(e){state.networkError=e.message||'Results unavailable';stats=emptyStats();entryData={entries:[],nextCursor:null};}if(state.screen!=='collective')return;state.community=stats;state.entries=entryData.entries||[];state.nextCursor=entryData.nextCursor||null;const total=Number(stats.total)||0;const counts=Array.from({length:5},(_,i)=>Number(stats.buckets?.[i]||0));articleFrame(`<div class="hero"><div class="eyebrow">Community imagery spectrum · After personal results</div><h1>Many minds. <span class="gradient">Different ways of seeing.</span></h1><p class="lede">${getSharedFlag()?'Every consented online contribution changes this shared picture.':'Only responses saved in this browser appear here.'} These percentages are not population prevalence. Only responses to assessment v2 are counted.</p></div>${!getSharedFlag()?`<div class="notice" style="margin-bottom:17px"><strong>Preview mode — this device only.</strong> The circles below include only v2 results recorded by this browser. To collect truly shared results across phones and computers, deploy the included Cloudflare Worker and D1 database.</div>`:''}${state.networkError?`<div class="notice" style="margin-bottom:17px">${esc(state.networkError)}. No substitute or invented community data is shown.</div>`:''}<section class="card"><div class="row between wraprow"><div><div class="kicker">${getSharedFlag()?'Collective visualization':'This-device visualization'}</div><h2 class="h2">The imagery spectrum</h2></div><span class="badge">${total.toLocaleString()} participant${total===1?'':'s'}</span></div><div class="ring-layout">${ringSVG(counts)}<div>${stages.map((st,i)=>{const n=counts[i];const ratio=total?(100*n/total):0;return `<div class="legend-row"><div class="dot" style="background:${st.color}"></div><div><strong>${esc(st.term)}</strong><span>${esc(st.plain)} · ${n} respondent${n===1?'':'s'}</span><div class="progress-stripe" style="margin-top:7px"><i style="background:${st.color};width:${ratio}%"></i></div></div><div class="percent">${ratio.toFixed(1)}%</div></div>`}).join('')}</div></div><p class="fine topspace">With zero respondents, all categories display 0.0%. Categories use custom quiz thresholds and should not be treated as epidemiological estimates.</p></section><section class="card chart-section"><div class="kicker">Group processing snapshot</div><h2 class="h2">Average correct by task type</h2><div class="grid3">${[['Spatial',stats.domains?.spatial,'#5ee3cb'],['Memory',stats.domains?.memory,'#a99cff'],['Reasoning',stats.domains?.reasoning,'#f4a3d8']].map(x=>`<div>${ringSmall((Number(x[1])||0)/5,x[0],x[2])}</div>`).join('')}</div><p class="fine topspace">These are average percentages correct on this short, unstandardized v2 challenge set. They do not show cognitive ability differences attributable to imagery.</p></section><section class="card chart-section"><div class="row between wraprow"><div><div class="kicker">${getSharedFlag()?'Voluntary individual listings':'Saved in this browser'}</div><h2 class="h2">${getSharedFlag()?'Participant results':'Local participant results'}</h2></div><span class="fine">Separate listing opt-in required</span></div><div id="entryList">${entriesHTML()}</div><button class="btn secondary topspace ${state.nextCursor?'':'hidden'}" id="loadMore">Show more participant results ↓</button><p class="fine topspace">Only people who opt into individual listings appear here. Public names and summary scores can be seen by anyone. Do not use this voluntary sample to diagnose anyone.</p></section><div class="card chart-section"><div class="h3">Want to compare your own results?</div><p class="muted small">${getSharedFlag()?'Send this public link to others. Consented results are combined in one online chart.':'Send friends an offline HTML test file. Each person can take it privately, but results do not synchronize across devices.'}</p><div class="row wraprow"><button class="btn" id="retake">Take the test →</button>${state.ratings.every(x=>x!==null)&&state.answers.every(x=>x!==null)?'<button class="btn secondary" id="myResults">My personal results</button>':''}<button class="btn secondary" id="shareLink">${getSharedFlag()?'Share public test link ↗':'Share offline HTML file ↗'}</button></div><p class="hint topspace" id="shareStatus" role="status"></p></div>${state.hasSubmitted&&getSharedFlag()?`<div class="card chart-section"><div class="kicker">Your private control</div><h3 class="h3">Delete your contribution</h3><p class="muted small">Your contribution is saved. The code below allows you to delete it later. Copy it somewhere private; anyone with the code could delete this entry.</p><div class="row wraprow"><button class="btn secondary" id="copyRecovery">Copy private deletion code</button><button class="btn secondary" id="deleteMine">Delete my saved result</button></div><p class="fine topspace" id="deleteMessage" role="status"></p></div>`:''}<div class="card chart-section"><details><summary>Delete a result using a saved recovery code</summary><p class="small muted topspace">If you saved a deletion code on another device, paste it here to remove that submission. This is separate from your current personal results.</p><input id="recoveryField" class="field" placeholder="Paste private recovery code" autocomplete="off" spellcheck="false" aria-label="Private deletion recovery code"><button class="btn secondary topspace" id="recoverDelete">Delete matching submission</button><p class="fine topspace" id="recoverStatus" role="status"></p></details></div>`);
$('#loadMore')?.addEventListener('click',loadMore);$('#retake').addEventListener('click',restart);$('#myResults')?.addEventListener('click',renderPersonal);$('#shareLink').addEventListener('click',async()=>{if(!getSharedFlag()){await shareOfflineTest();return;}const shareUrl=SHARED_TEST_URL||location.href;if(navigator.share){try{await navigator.share({title:"Mind's Eye Atlas",text:'Explore your visual imagination and compare results.',url:shareUrl})}catch(e){if(e.name!=='AbortError')copyText(shareUrl,'shareLink')}}else copyText(shareUrl,'shareLink');});
$('#copyRecovery')?.addEventListener('click',()=>copyText(recoveryCode(),'copyRecovery'));
$('#deleteMine')?.addEventListener('click',async()=>{
 if(!confirm('Permanently remove this contribution from the online results?'))return;
 const b=$('#deleteMine');b.disabled=true;
 try{await api('delete',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({id:state.submissionId,deletionToken:state.deletionToken})});
  state.hasSubmitted=false;state.submissionId=null;state.deletionToken=null;state.consent=false;state.publicEntry=false;
  try{localStorage.removeItem('mindseye-recovery-v2')}catch{};renderCollective();
 }catch(e){$('#deleteMessage').textContent=e.message;b.disabled=false;}
});
$('#recoverDelete')?.addEventListener('click',async()=>{
 const raw=$('#recoveryField').value.trim(),sep=raw.indexOf(':'),id=raw.slice(0,sep),deletionToken=raw.slice(sep+1);
 if(sep<1||!/^[a-f0-9]{64}$/.test(deletionToken)){$('#recoverStatus').textContent='Invalid recovery code.';return;}
 if(!confirm('Delete the result associated with this recovery code?'))return;
 try{await api('delete',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({id,deletionToken})});
  if(state.submissionId===id){state.hasSubmitted=false;state.submissionId=null;state.deletionToken=null;state.consent=false;}
  try{if(localStorage.getItem('mindseye-recovery-v2')===raw)localStorage.removeItem('mindseye-recovery-v2')}catch{};
  renderCollective();
 }catch(e){$('#recoverStatus').textContent=e.message;}
});
}
// Share a pristine file, not the live DOM containing a participant's name or scores.
function cleanOfflineFile(){
 const cloned=document.documentElement.cloneNode(true);
 const app=cloned.querySelector('#app');if(app)app.replaceChildren();
 const connection=cloned.querySelector('#connection');if(connection)connection.textContent='Offline / private preview';
 return new File(['<!doctype html>\n',cloned.outerHTML], 'Minds_Eye_Atlas_Offline_Preview.html',{type:'text/html;charset=utf-8'});
}
function downloadOfflineFile(file){
 const href=URL.createObjectURL(file),a=document.createElement('a');
 a.href=href;a.download=file.name;document.body.appendChild(a);a.click();a.remove();
 setTimeout(()=>URL.revokeObjectURL(href),15000);
}
async function shareOfflineTest(){
 const status=$('#shareStatus');const report=t=>{if(status)status.textContent=t};
 let file;try{file=cleanOfflineFile()}catch{report('Could not make a clean HTML copy. Please share the original downloaded HTML from your Files app.');return}
 if(navigator.share&&navigator.canShare?.({files:[file]})){
  try{await navigator.share({title:"Mind's Eye Atlas",text:'A private interactive mental imagery test (HTML file). Each device stores results separately.',files:[file]});report('The test file was handed to Android sharing. Results are not combined across devices.');return}
  catch(e){if(e.name==='AbortError'){report('Sharing cancelled.');return}}
 }
 try{downloadOfflineFile(file);report('Saved a clean HTML test file. Open Downloads and use Share to send it. This is not a public web link; each device keeps its own results.')}
 catch{report('Sharing is not supported by this browser. In Android Files, share the original HTML download instead.')}
}
async function loadMore(){if(!state.nextCursor)return;const btn=$('#loadMore');btn.disabled=true;btn.textContent='Loading…';try{const v=await loadEntries(state.nextCursor);state.entries.push(...(v.entries||[]));state.nextCursor=v.nextCursor||null;$('#entryList').innerHTML=entriesHTML();btn.classList.toggle('hidden',!state.nextCursor);}catch(e){btn.textContent='Retry loading results';}finally{btn.disabled=false;if(state.nextCursor&&btn.textContent!=='Retry loading results')btn.textContent='Show more participant results ↓';}}
async function detectMode(){
 if(location.protocol==='file:'){state.network=false;$('#connection').textContent='Offline / local preview';updateSharingNotice();return;}
 try{const data=await api('status');if(data?.online!==true)throw Error('Database connection not ready');SHARED_TEST_URL=data.url||location.origin;state.network=true;$('#connection').textContent='Private Cloudflare storage';}
 catch(e){state.network=false;state.networkError=e.message||'Could not reach the Cloudflare database';$('#connection').textContent='Online service unavailable';}
 updateSharingNotice();
}
renderIntro();detectMode();

